 {name:'Área de retângulos',level:'Desafio',module:'Geometria',intro:'Descubra quantos quadradinhos cobrem uma superfície retangular.',rule:'Área do retângulo é base × altura, em unidades quadradas.',steps:['Identifique a base e a altura.','Multiplique as medidas.','Use unidade quadrada: cm², m² etc.'],example:'Um retângulo de 5 cm por 3 cm tem 15 cm².',type:22},
 {name:'Desafios de consumo consciente',level:'Desafio',module:'Problemas',intro:'Planeje compras hipotéticas, calcule totais e confira decisões.',rule:'Multiplique a quantidade pelo preço unitário; compare depois com o orçamento.',steps:['Encontre a quantidade e o preço de cada item.','Multiplique para achar o custo total.','Se houver orçamento, compare valores e encontre o saldo.'],example:'3 cadernos de R$ 8 custam R$ 24.',type:23}
