 $('studyBtn').addEventListener('click',()=>{let rec=studyRecommendation();selectLesson(rec.index);$('challengeTitle').scrollIntoView({block:'start',behavior:'smooth'});});
 $('studyTarget').addEventListener('click',()=>{let rec=studyRecommendation();selectLesson(rec.index);$('challengeTitle').scrollIntoView({block:'start',behavior:'smooth'});});
